std::string trim(std::string_view text){while(!text.empty()&&std::isspace(static_cast<unsigned char>(text.front())))text.remove_prefix(1);while(!text.empty()&&std::isspace(static_cast<unsigned char>(text.back())))text.remove_suffix(1);return std::string(text);}
double attribute(const tinyxml2::XMLElement* node,const char* name,double fallback=0){const auto* text=node->Attribute(name);if(!text)return fallback;auto values=numbers(text);if(values.size()!=1)throw Error("invalid_argument",std::string("SVG attribute requires one numeric user-unit value: ")+name);return values[0];}
std::string paint_keyword(std::string_view value){
  auto result=trim(value);
  // CSS paint keywords/functions are ASCII case insensitive. Escaped tokens,
  // variables and contextual paints need CSS resolution outside this subset.
  if(result.find('\\')!=std::string::npos)throw Error("unsupported_format","SVG escaped paint tokens are unsupported");
  for(auto& c:result)if(c>='A'&&c<='Z')c=static_cast<char>(c-'A'+'a');
  return result;
}
void attributes(const tinyxml2::XMLElement* node,std::set<std::string> allowed){
  for(const auto* name:{"id","transform","fill","fill-rule","stroke"})allowed.insert(name);
  for(auto a=node->FirstAttribute();a;a=a->Next())if(!allowed.contains(a->Name()))throw Error("unsupported_format",std::string("Unsupported SVG attribute: ")+a->Name());
  if(const auto* fill=node->Attribute("fill")){const auto paint=paint_keyword(fill);if(paint=="none"||paint.find("url(")!=std::string::npos||paint.find("var(")!=std::string::npos||paint=="context-fill"||paint=="context-stroke")throw Error("unsupported_format","SVG authoring requires filled geometry without paint servers or contextual CSS paints");}
  if(const auto* stroke=node->Attribute("stroke");stroke&&paint_keyword(stroke)!="none")throw Error("unsupported_format","SVG stroked geometry requires an explicit filled outline");
}
