struct DxfPair {int code;std::string value;};
using DxfEntity=std::vector<DxfPair>;
int integer(std::string_view text){const auto token=trim(text);double v=0;if(!parse_decimal(token,v)||v!=std::trunc(v)||std::abs(v)>1000000)throw Error("invalid_argument","Expected a bounded DXF integer");return static_cast<int>(v);}
double decimal(std::string_view text){const auto token=trim(text);double v=0;if(!parse_decimal(token,v)||std::abs(v)>1000000)throw Error("invalid_argument","Expected a finite bounded DXF coordinate");return v;}
std::optional<std::string> dxf_value(const DxfEntity& e,int code){std::optional<std::string> result;for(const auto& p:e)if(p.code==code){if(result)throw Error("invalid_argument","Unexpected repeated DXF scalar group",{{"group_code",code}});result=p.value;}return result;}
double dxf_number(const DxfEntity& e,int code,double fallback=0){const auto value=dxf_value(e,code);return value?decimal(*value):fallback;}
int dxf_integer(const DxfEntity& e,int code,int fallback=0){const auto value=dxf_value(e,code);return value?integer(*value):fallback;}
